type ColorSliderOwnProps = {
  label?: Exclude<React.ReactNode, null | undefined | boolean>;
  value?: MuxUIColorValue;
  defaultValue?: MuxUIColorValue;
  onChange?: (value: MuxUIColorValue) => void;
  channel?: MuxUIColorChannel;
  colorSpace?: MuxUIColorSpace;
  disabled?: boolean;
  readOnly?: boolean;
  orientation?: 'horizontal' | 'vertical';
};

type ColorSliderProps = Omit<ColorSliderOwnProps, 'label'> & {
  className?: string;
} & MuxUIAccessibleName;

type MuxUIAccessibleName = {
  label: Exclude<React.ReactNode, null | undefined | boolean>;
  'aria-label'?: never;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label'?: never;
  'aria-labelledby': string;
};
